const D = { density: .55, scale: 1, energy: .55, hue: 210, speed: 1, x: .5, y: .4, seed: 0, style: 'soft', act: 'drift' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const TAU = 6.28318530718;
const cl = (v,a,b) => v<a?a:v>b?b:v;
const sty = P.style;
const um = Math.min(width,height);
const H = P.hue;
const hz = cl(P.y,.18,.7) * height;
const groundH = Math.max(30, height - hz);
const yOf = t => hz + Math.pow(t,1.7) * groundH;
const H_top = sty==='storm' ? (H+8) : H;

S.bass = (S.bass||0)*.82 + (A.bass||0)*.18;
S.tre  = (S.tre ||0)*.82 + (A.treble||0)*.18;
const glow = (.4 + .6*P.energy) * (.5 + .6*K.intensity);
const kick = Math.min(1, K.pulse*(.5+.5*K.intensity) + S.bass*.7);
const breathe = 1 + .07*P.energy*(0.5 + 0.5*K.swell);

// ---- real-time inflow scroll (never re-phases) ----
if (S.pt == null || K.t < S.pt) S.pt = K.t;
let dt = K.t - S.pt; S.pt = K.t; dt = cl(dt,0,.1);
let sp = P.speed * (.5 + .7*K.intensity);
if (P.act === 'gale') sp *= 1.6 + .5*Math.sin(K.t*.4);
if (P.act === 'swell') sp *= .6 + .4*(.5+.5*Math.sin(K.t*.06));
S.scroll = (S.scroll||0) + dt*sp*.06;
const scroll = S.scroll;

// ---- soft puff sprite (built once per style/seed) ----
if (S.spr == null || S.sprKey !== sty+'|'+P.seed){
  const sz=128, sp2=createGraphics(sz,sz); sp2.colorMode(HSB,360,100,100,100); sp2.clear(); sp2.noStroke();
  const c=sz/2;
  if (sty==='contour'){
    sp2.noFill();
    for (let i=6;i>=1;i--){ const rr=(i/6)*sz*.46; sp2.stroke(0,0,100, 34+i*8); sp2.strokeWeight(2.2);
      sp2.beginShape();
      for (let a=0;a<=24;a++){ const ang=a/24*TAU; const wob=1+.12*Math.sin(ang*3+i)+.08*Math.sin(ang*5+i*2);
        sp2.vertex(c+Math.cos(ang)*rr*wob, c+Math.sin(ang)*rr*.8*wob); }
      sp2.endShape(CLOSE);
    }
  } else {
    for (let i=44;i>=0;i--){ const t=i/44, rr=t*sz*.5, a=(1-t)*(1-t)*100;
      sp2.fill(0,0,100, a*.92); sp2.ellipse(c,c,rr*2,rr*2*.8); }
    if (sty==='ukiyo'){ sp2.noFill(); sp2.stroke(0,0,100,95); sp2.strokeWeight(3.2); sp2.ellipse(c,c,sz*.88,sz*.7);
      sp2.strokeWeight(1.6); sp2.stroke(0,0,100,50); sp2.ellipse(c,c,sz*.6,sz*.48); }
  }
  S.spr=sp2; S.sprKey=sty+'|'+P.seed;
}

// ---- cached sky + far cloud wash ----
const key = width+'x'+height+'|'+sty+'|'+Math.round(H)+'|'+Math.round(hz);
if (!S.base || S.key !== key){
  const g = S.base && S.base.width===width && S.base.height===height ? S.base : createGraphics(width,height);
  g.colorMode(HSB,360,100,100,100); g.clear(); g.noStroke();
  const STR=56;
  for (let i=0;i<STR;i++){ const f=i/STR, y=f*hz; let h,s,b;
    if (sty==='storm'){ h=(H+6); s=18-8*f; b=30+14*f; }
    else if (sty==='contour'){ h=H; s=30-14*f; b=10+8*f; }
    else if (sty==='ukiyo'){ h=(H-6); s=22-10*f; b=78+12*f; }
    else { h=(H-8+10*f); s=42-26*f; b=62+26*f; }   // soft dawn sky
    g.fill(h,cl(s,2,90),cl(b,4,94),100); g.rect(0,y,width,hz/STR+1);
  }
  // carpet base wash below horizon
  for (let i=0;i<STR;i++){ const t=i/STR, y=yOf(t), y2=yOf((i+1)/STR); let h,s,b;
    if (sty==='storm'){ h=(H+4); s=12+8*t; b=cl(40-24*t,10,60); }
    else if (sty==='contour'){ h=H; s=24; b=6+10*t; }
    else if (sty==='ukiyo'){ h=(H-4); s=10; b=cl(90-14*t,60,92); }
    else { h=(H-6); s=16-6*t; b=cl(84-10*t,50,92); }
    g.fill(h,cl(s,2,90),b,100); g.rect(0,y,width,(y2-y)+1);
  }
  S.base=g; S.key=key;
}
image(S.base,0,0);

// ---- god-glow shafts from below (real-time, gated by intensity) ----
const gg = cl((K.intensity-0.35)*1.4 + (P.act==='swell'?0.35:0) + K.swell*.15, 0, 1);
if (gg>0.03 && sty!=='storm'){ push(); blendMode(ADD); noStroke();
  const sx=cl(P.x,0,1)*width, sy=height*1.15;
  const rays=6;
  for (let i=0;i<rays;i++){ const base=(i+.5)/rays*width;
    const sw=Math.sin(K.t*.25 + i)*width*.04;
    const topY=hz + groundH*.15;
    fill((H+30)%360, 26, 100, 5*gg*glow);
    quad(sx-6, sy, sx+6, sy, base+width*.06+sw, topY, base-width*.06+sw, topY);
  }
  pop();
}

// ---- billowing cumulus puffs (perspective inflow) ----
const NP = Math.round(22 + P.density*70);
const puffs = [];
for (let i=0;i<NP;i++){
  const t = ((fr(i*5) + scroll*(0.4+0.9*fr(i*5+4))) % 1);
  if (t<=0.02) continue;
  puffs.push({ i, t });
}
puffs.sort((a,b)=>a.t-b.t);
push();
const upH = sty==='storm'? 22 : (sty==='ukiyo'?4 : 10);
const upS = sty==='storm'? 14 : (sty==='contour'?30 : 22);
for (const pf of puffs){ const i=pf.i, t=pf.t;
  const y=yOf(t);
  const lane=fr(i*5+1);
  const drift=Math.sin(K.t*(.18+.12*fr(i*5+2)) + i)*width*.05*(0.5+P.energy);
  const x=(lane*1.5-0.25)*width + drift;
  const base=um*(.05+.5*t)*cl(P.scale,.35,2.2)*(0.7+0.7*fr(i*5+3));
  const w=base*breathe*(1+.2*Math.sin(K.t*.3+i));
  const h=w*0.72;
  const lit = 0.5+0.5*Math.sin(K.t*.2+i*1.3);
  // underside shadow copy
  if (sty!=='contour'){
    tint((H+upH)%360, upS+8, sty==='storm'? cl(38-14*t,10,44): cl(58-18*t,30,70), cl(30*t+8,4,42)*(0.6+0.6*glow));
    image(S.spr, x-w/2, y-h/2 + h*0.16, w, h);
  }
  // lit crown
  const topB = sty==='storm'? cl(52-10*t + 16*lit,20,72) : cl(80-8*t + 14*lit,50,94);
  tint(H_top, sty==='storm'? (16-6*t) : (sty==='contour'?70:(18-8*t)), topB, cl(46*t+14,6,60)*(0.6+0.7*glow));
  image(S.spr, x-w/2, y-h/2, w, h);
}
pop();
noTint();

// ---- rim light on beat (partial, real-time) ----
push(); blendMode(ADD); noStroke();
const flare=(kick*.5 + K.swell*.35)*glow;
for (let i=0;i<4;i++){ const rr=(4-i)*groundH*.05*(1+flare);
  fill((H+24)%360, sty==='storm'?10:30, 100, 4+7*flare*(sty==='storm'?.4:1));
  rect(0, hz-rr*.5, width, rr); }
pop();

// ---- storm lightning (partial-frame flash, safe) ----
if (sty==='storm'){
  if (S.lt==null) S.lt=0;
  if (kick>0.7 && fr(Math.floor(K.beat))>0.6 && S.lt<0.05) S.lt=1;
  S.lt = Math.max(0, (S.lt||0) - dt*4);
  if (S.lt>0.02){ push(); blendMode(ADD); noStroke();
    const lx=cl(P.x + (fr(Math.floor(K.beat)*3)-.5)*.4,0,1)*width;
    fill((H+20)%360, 8, 100, 30*S.lt);
    rect(lx-width*.18, 0, width*.36, hz*1.1);
    stroke(0,0,100,80*S.lt); strokeWeight(2);
    let ly=0, lxx=lx; beginShape(); noFill();
    for (let s0=0;s0<6;s0++){ vertex(lxx,ly); lxx += (fr(s0+Math.floor(K.beat))-.5)*um*.08; ly += hz/5; }
    endShape();
    pop();
  }
}

blendMode(BLEND);
noTint();
drawingContext.shadowBlur = 0;
